{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    allocations = [seg['minimum'] for seg in segments]
    remaining = budget - sum(allocations)
    if remaining < 0:
        deficit = -remaining
        sorted_indices = sorted(range(n), key=lambda i: segments[i]['importance'])
        for idx in sorted_indices:
            if deficit <= 0:
                break
            reduction = min(deficit, allocations[idx])
            allocations[idx] -= reduction
            deficit -= reduction
    else:
        sorted_indices = sorted(range(n), key=lambda i: segments[i]['importance'], reverse=True)
        for idx in sorted_indices:
            if remaining <= 0:
                break
            seg = segments[idx]
            max_extra = seg['capacity'] - allocations[idx]
            extra = min(remaining, max_extra)
            allocations[idx] += extra
            remaining -= extra
    by_name = {segments[i]['name']: allocations[i] for i in range(n)}
    total = sum(allocations)
    return {"allocations": allocations, "by_name": by_name, "total": total}"
}
